// Searchable list of places in India for Settings > Location: every district,
// well-known towns that are not district names, and two towns in each very wide
// district. Pure data + matching; works offline. The data (coordinates and
// elevation) is generated by tools/build-india-places.py into india-places-data.js.
(function (global) {
  "use strict";
  const VedicEngine = global.VedicEngine = global.VedicEngine || {};
  const DATA = VedicEngine.IndiaPlacesData || { districts: [], towns: [] };

  // Old / alternate spellings people still type -> the place they mean (by name).
  const ALIASES = {
    "Bengaluru Urban": ["Bangalore", "Bengaluru", "Bangalore Urban"], "Bengaluru Rural": ["Bangalore Rural"],
    "Mysuru": ["Mysore"], "Mangaluru": ["Mangalore"], "Hubballi": ["Hubli"], "Belagavi": ["Belgaum"],
    "Kalaburagi": ["Gulbarga"], "Ballari": ["Bellary"], "Vijayapura": ["Bijapur"], "Shivamogga": ["Shimoga"],
    "Tumakuru": ["Tumkur"], "Kochi": ["Cochin"], "Thiruvananthapuram": ["Trivandrum"], "Kozhikode": ["Calicut"],
    "Thrissur": ["Trichur"], "Alappuzha": ["Alleppey"], "Chennai": ["Madras"], "Tiruchirappalli": ["Trichy", "Tiruchchirappalli"],
    "Puducherry": ["Pondicherry", "Pondy"], "Thanjavur": ["Tanjore"], "Kanniyakumari": ["Kanyakumari", "Cape Comorin"],
    "Kanyakumari": ["Kanniyakumari", "Cape Comorin"], "Kolkata": ["Calcutta"], "Mumbai City": ["Bombay", "Mumbai"],
    "Mumbai Suburban": ["Bombay", "Mumbai"], "Pune": ["Poona"], "Prayagraj": ["Allahabad"], "Varanasi": ["Banaras", "Benares", "Kashi"],
    "Gurugram": ["Gurgaon"], "Vadodara": ["Baroda"], "Visakhapatnam": ["Vizag", "Vishakhapatnam"], "Kanpur Nagar": ["Cawnpore", "Kanpur"],
    "Ayodhya": ["Faizabad"], "Chhatrapati Sambhajinagar": ["Aurangabad"], "Aurangabad": ["Sambhajinagar"], "Osmanabad": ["Dharashiv"],
    "Ahmednagar": ["Ahilyanagar"], "Dharashiv": ["Osmanabad"], "Puri": ["Jagannath Puri"], "Rishikesh": ["Hrishikesh"],
    "Panaji": ["Panjim"], "Somnath": ["Veraval", "Prabhas Patan"], "Śṛṅgeri": ["Sringeri", "Shringeri", "Sringeri Sharada Peetham"],
    "Melukote": ["Melkote", "Melukote Cheluvanarayana"], "Hyderabad": ["Bhagyanagar"], "Gaya": ["Bodh Gaya", "Bodhgaya"],
    "Kutch": ["Kachchh", "Kachh", "Bhuj"], "Dwarka": ["Dwaraka"],
  };

  // Folds a spelling to a rough sound-alike key so Indian-name variants meet:
  // accents off, aa/ee/oo -> a/i/u, w -> v, y -> i, h dropped, doubled letters merged.
  function fold(s) {
    return String(s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase()
      .replace(/[^a-z ]+/g, " ").replace(/aa+/g, "a").replace(/(ee|ii)+/g, "i").replace(/(oo|uu)+/g, "u")
      .replace(/w/g, "v").replace(/y/g, "i").replace(/z/g, "j").replace(/h/g, "").replace(/(.)\1+/g, "$1")
      .replace(/\s+/g, " ").trim();
  }
  // Plain version: accents off, lower case, letters/digits/space only (used for exact and regex matching).
  function plain(s) {
    return String(s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
  }

  const PLACES = [];
  DATA.towns.forEach(function (t) {
    // [name, district, state, lat, lon, elevation]
    PLACES.push({ name: t[0], state: t[2], district: t[1], kind: "town", latitude: t[3], longitude: t[4], elevation: t[5],
      label: t[0] + (t[1] ? ", " + t[1] + " district" : "") + ", " + t[2] });
  });
  DATA.districts.forEach(function (st) {
    st[1].forEach(function (d) {
      // [name, lat, lon, elevation]
      PLACES.push({ name: d[0], state: st[0], district: d[0], kind: "district", latitude: d[1], longitude: d[2], elevation: d[3],
        label: d[0] + " (district), " + st[0] });
    });
  });
  PLACES.forEach(function (p) {
    const alts = ALIASES[p.name] || [];
    p.plain = plain(p.label);
    p.fold = fold(p.name + " " + (p.kind === "town" ? p.district + " " : "") + p.state + " " + alts.join(" "));
    p.nameFold = fold(p.name);
    p.altFolds = alts.map(fold);
  });

  // The user typed a regular expression: /.../ , or any regex metacharacter.
  const REGEX_HINT = /^\/.+\/[i]?$|[\^$*+?|()[\]{}\\]/;
  function userRegex(query) {
    const m = /^\/(.+)\/i?$/.exec(query);
    try { return new RegExp(m ? m[1] : query, "i"); } catch (e) { return null; }
  }

  // Lower rank = better match; null = no match.
  function rank(p, tokens, subseq) {
    let worst = 0;
    for (let i = 0; i < tokens.length; i++) {
      const t = tokens[i];
      let r;
      if (p.nameFold === t || p.altFolds.indexOf(t) !== -1) r = 0;
      else if (p.nameFold.indexOf(t) === 0 || p.altFolds.some(function (a) { return a.indexOf(t) === 0; })) r = 1;
      else if ((" " + p.fold).indexOf(" " + t) !== -1) r = 2;
      else if (p.fold.indexOf(t) !== -1) r = 3;
      else if (subseq && subseq.test(p.nameFold)) r = 4;
      else return null;
      if (r > worst) worst = r;
    }
    return worst;
  }

  // Best matches for what the user typed, best first.
  //  - "/^ra.*pur$/" or anything with regex symbols is used as a regular expression on the label;
  //  - otherwise every word typed must match (sound-alike folded, so "mysore", "banaras", "trichy",
  //    "dehradoon" or "pune maharashtra" all work), by name, alias, district or state;
  //  - a single word that matches nothing is tried as letters-in-order with small gaps ("pne" finds Pune).
  function search(query, limit) {
    const q = String(query || "").trim();
    if (!q) return [];
    limit = limit || 12;
    let hits;
    if (REGEX_HINT.test(q) && userRegex(q)) {
      const re = userRegex(q);
      // on the bare name (so ^ and $ mean the start/end of the name) or on the whole label
      hits = PLACES.filter(function (p) { return re.test(plain(p.name)) || re.test(p.plain); }).map(function (p) { return { p: p, r: 0 }; });
    } else {
      const tokens = fold(q).split(" ").filter(Boolean);
      if (!tokens.length) return [];
      hits = [];
      PLACES.forEach(function (p) {
        const r = rank(p, tokens, null);
        if (r !== null) hits.push({ p: p, r: r });
      });
      // Nothing matched: allow a typo - the letters in order from the same first letter, with at
      // most two other letters between each ("pne" finds Pune, "varansi" finds Varanasi).
      const letters = tokens.join("");
      if (!hits.length && tokens.length === 1 && letters.length >= 3) {
        const subseq = new RegExp("^" + letters.split("").join(".{0,2}"));
        PLACES.forEach(function (p) { if (subseq.test(p.nameFold)) hits.push({ p: p, r: 4 }); });
      }
    }
    hits.sort(function (a, b) {
      return a.r - b.r || (a.p.kind === b.p.kind ? 0 : a.p.kind === "town" ? -1 : 1) || (a.p.label < b.p.label ? -1 : 1);
    });
    return hits.slice(0, limit).map(function (h) { return h.p; });
  }

  // Exact lookup by full label or bare name (accent- and case-insensitive).
  function find(text) {
    const t = plain(text);
    if (!t) return null;
    return PLACES.filter(function (p) { return p.plain === t; })[0] ||
      PLACES.filter(function (p) { return plain(p.name) === t; })[0] || null;
  }

  VedicEngine.IndiaPlaces = { PLACES: PLACES, find: find, search: search, fold: fold };
})(typeof window !== "undefined" ? window : globalThis);
